package fraymus.workspace;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
final class PoseStudy {
 static final String PROCEDURE="pose-evaluation-v1",SCOPE="Feature validation of a virtual force/torque gripper on multiple native bodies. Translation-only ablation is newly declared034, not the preserved033 contact pusher or a trained-policy comparison.";
 static JSONObject suite(){try(var in=PoseStudy.class.getResourceAsStream("/pose-tasks034.json")){return new JSONObject(new String(in.readAllBytes(),StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException(e);}}
 static JSONObject source(JSONObject c,String job){return SpatialScene.parse(c.getJSONObject("source").toString(),UUID.nameUUIDFromBytes(("pose:"+job+":"+c.getString("id")).getBytes(StandardCharsets.UTF_8)).toString());}
 static JSONObject plan(JSONObject c,String job){var s=source(c,job);return PosePlan.build(s,PosePlan.intent(s,c.getJSONArray("targets"),c.getDouble("forceLimitN"),c.getDouble("torqueLimitNm")));}
 static String identity(){var s=new StringBuilder(PoseCheckpoint.identity()).append(PushLearning.hash(suite()));for(Class<?> type:new Class<?>[]{PoseStudy.class,PoseStudyStore.class,PoseStudyReport.class})try(var in=type.getResourceAsStream(type.getSimpleName()+".class")){s.append(MapDefinition.sha(in.readAllBytes()));}catch(Exception e){throw new IllegalStateException(e);}return MeasurementStore.hash(s.toString());}
 static JSONObject decide(JSONObject suite,JSONArray rows){int dev=0,eval=0,base=0,devExpected=0,evalExpected=0,negative=0,regression=0,matched=0;double a=0,b=0,allA=0,allB=0,timeA=0,timeB=0;var pairs=new JSONArray();
  for(Object raw:suite.getJSONArray("cases")){var c=(JSONObject)raw;JSONObject left=null,right=null;for(Object value:rows){var r=(JSONObject)value;if(!r.getString("caseId").equals(c.getString("id")))continue;if(r.getString("arm").equals("baseline")){if(left!=null)throw new IllegalStateException("Duplicate pose baseline");left=r;}else if(r.getString("arm").equals("candidate")){if(right!=null)throw new IllegalStateException("Duplicate full-pose case");right=r;}else throw new IllegalStateException("Unknown pose arm");}if(left==null||right==null)throw new IllegalStateException("Complete original paired pose results required");var lm=left.getJSONObject("metrics");var rm=right.getJSONObject("metrics");boolean lp=lm.getBoolean("passed"),rp=rm.getBoolean("passed"),ev=c.getString("split").equals("evaluation"),neg=c.getBoolean("negativeControl");if(lp&&!rp)regression++;if(neg&&(lp||rp))negative++;if(!neg){if(ev){evalExpected++;if(rp)eval++;if(lp)base++;}else{devExpected++;if(rp)dev++;}}
   double lt=lp?lm.getDouble("timeS"):suite.getDouble("failedSeconds"),rt=rp?rm.getDouble("timeS"):suite.getDouble("failedSeconds");if(ev){timeA+=lt;timeB+=rt;allA+=lm.getDouble("effortNs");allB+=rm.getDouble("effortNs");if(lp&&rp&&!neg){matched++;a+=lm.getDouble("effortNs");b+=rm.getDouble("effortNs");}}
   pairs.put(new JSONObject().put("caseId",c.getString("id")).put("split",c.getString("split")).put("negativeControl",neg).put("baselinePassed",lp).put("candidatePassed",rp).put("baselineTimeS",lt).put("candidateTimeS",rt).put("baselineEffortNs",lm.getDouble("effortNs")).put("candidateEffortNs",rm.getDouble("effortNs")).put("baselineAngleDeg",lm.getDouble("maxAngleErrorDeg")).put("candidateAngleDeg",rm.getDouble("maxAngleErrorDeg")).put("baselineProtectedDriftM",lm.getDouble("maxInactiveDriftM")).put("candidateProtectedDriftM",rm.getDouble("maxInactiveDriftM")).put("baselineRunId",left.getString("runId")).put("candidateRunId",right.getString("runId")));
  }
  var g=suite.getJSONObject("gates");double ratio=matched==0?1e9:b/Math.max(1e-9,a);boolean accepted=dev==devExpected&&eval==evalExpected&&negative==0&&regression==0&&matched>=g.getInt("minMatchedSuccessCases")&&ratio<=g.getDouble("maxMatchedSuccessEffortRatio");return new JSONObject().put("passed",true).put("accepted",accepted).put("developmentPositivePasses",dev).put("developmentPositiveCases",devExpected).put("evaluationPositivePasses",eval).put("evaluationPositiveCases",evalExpected).put("baselineEvaluationPositivePasses",base).put("negativeControlErrors",negative).put("successRegressions",regression).put("matchedSuccessCases",matched).put("matchedSuccessEffortRatio",ratio).put("allCaseEffortRatio",allB/Math.max(1e-9,allA)).put("meanPenalizedTimeGainS",(timeA-timeB)/PushLearning.cases(suite,"evaluation").length()).put("pairs",pairs).put("gates",g).put("scope",suite.getString("scope"));
 }
}
